/*
 * Fund Dashboard - Fund Data Module
 * All data sourced from Morningstar MCP
 * Last updated: 2026-10-04 (data as of 2026-09-30)
 * Currency: NOK for all display values
 * Total funds: 12 (6 Equity + 6 Fixed Income)
 *
 * CORRECTED NOK methodology (v2):
 * Share-class currency determined from investment_name (NOT LS468 portfolio currency).
 * F00001GW7Y "GQG NOK Acc" → NOK (use HP010 directly)
 * F00001GU8B "Cusana NOK" → NOK (use HP010 directly)
 * F0000125XE "Wellington USD" → convert HP010 USD→NOK via Norges Bank
 * F00000ZFGS "Artisan USD" → convert HP010 USD→NOK via Norges Bank
 * F00000OAR8 "Brandes USD" → convert HP010 USD→NOK via Norges Bank
 * All fixed income NOK-hedged/NOK classes → use HP010 directly
 *
 * Predecessor stitching:
 * - GQG: F000011K3O (USD) → F00001GW7Y (NOK Acc, from 2024-02)
 * - PIMCO: F00000YHRH (NOK H) → F00001EWFB (NOK H, from 2023-04)
 * - PGIM: F0000151UQ (NOK H) → F000014RM8 (NOK H, from 2021-03)
 * - Danske Norsk Obligasjon: F00001SEZF → F00001SEG2 (from 2025-11)
 */

